INSERT INTO tiny_houses VALUES
(1, TIMESTAMP '2026-05-21 18:38:29.820702', FALSE, TIMESTAMP '2026-05-21 18:38:29.820702', 0, TRUE, 'Beykoz Korusu Yolu No:15', TRUE, 4.80, 1, 2, 4, U&'\0130stanbul', 150.00, U&'\0130stanbul Bo\011faz\0131''n\0131n e\015fsiz manzaras\0131na sahip, modern tasar\0131ml\0131 tiny house. Tam donan\0131ml\0131 mutfak, rahat yatak ve geni\015f teras ile unutulmaz bir konaklama deneyimi sunar.', 'Beykoz', 41.1325, 29.0965, 850.00, TRUE, FALSE, 2, U&'Bo\011faz Manzaral\0131 Modern Tiny House', TRUE, 2),
(2, TIMESTAMP '2026-05-21 18:38:29.828194', FALSE, TIMESTAMP '2026-05-21 18:38:29.828194', 0, TRUE, 'Sahil Yolu Cad. No:42', TRUE, 4.60, 1, 1, 2, U&'\0130stanbul', 100.00, U&'Prens Adalar\0131 manzaras\0131na bakan, sahile s\0131f\0131r konumda romantik tiny house. Deniz sesi e\015fli\011finde huzurlu bir tatil i\00e7in ideal.', 'Maltepe', 40.9332, 29.1355, 720.00, FALSE, TRUE, 1, U&'Adalar Manzaral\0131 Sahil Evi', TRUE, 2),
(3, TIMESTAMP '2026-05-21 18:38:29.831247', FALSE, TIMESTAMP '2026-05-21 18:38:29.831247', 0, TRUE, 'Olimpos Yolu Km:3', FALSE, 4.90, 1, 2, 3, 'Antalya', 75.00, U&'Olimpos''un e\015fsiz do\011fas\0131nda, \00e7am ormanlar\0131 aras\0131nda konumlanm\0131\015f rustic tarzda tiny house. Antik kent y\00fcr\00fcy\00fc\015f mesafesinde.', 'Kumluca', 36.3957, 30.4728, 550.00, TRUE, TRUE, 1, 'Olimpos Orman Evi', TRUE, 3),
(4, TIMESTAMP '2026-05-21 18:38:29.835199', FALSE, TIMESTAMP '2026-05-21 18:38:29.835199', 0, TRUE, U&'\00c7ukurba\011f Yar\0131madas\0131 No:8', TRUE, 4.70, 2, 2, 4, 'Antalya', 200.00, U&'Ka\015f''\0131n turkuaz sular\0131na bakan, \00f6zel havuzlu l\00fcks tiny house. Akdeniz mimarisinden esinlenilmi\015f tasar\0131m\0131yla g\00f6z kama\015ft\0131r\0131yor.', U&'Ka\015f', 36.2001, 29.6389, 1200.00, TRUE, FALSE, 2, U&'Ka\015f Deniz Manzaral\0131 Villa Tiny', TRUE, 3),
(5, TIMESTAMP '2026-05-21 18:38:29.835199', FALSE, TIMESTAMP '2026-05-21 18:38:29.835199', 0, TRUE, U&'Babada\011f Ete\011fi K\00f6yi\00e7i No:23', TRUE, 4.85, 1, 1, 2, U&'Mu\011fla', 100.00, U&'\00d6l\00fcdeniz''in \00fcnl\00fc lag\00fcn\00fcne tepeden bakan, panoramik manzaral\0131 da\011f evi. Yama\00e7 para\015f\00fct\00fc pistine yak\0131n konumda.', 'Fethiye', 36.5501, 29.1167, 680.00, TRUE, FALSE, 1, U&'Fethiye \00d6l\00fcdeniz Da\011f Evi', TRUE, 2),
(6, TIMESTAMP '2026-05-21 18:38:29.841529', FALSE, TIMESTAMP '2026-05-21 18:38:29.841529', 0, TRUE, U&'G\00fcm\00fc\015fl\00fck Mah. Sahil Sk. No:7', TRUE, 4.50, 1, 2, 3, U&'Mu\011fla', 150.00, U&'Bodrum''un tarihi dokusuna uygun ta\015f mimarisiyle in\015fa edilmi\015f butik tiny house. G\00fcm\00fc\015fl\00fck sahiline y\00fcr\00fcme mesafesinde.', 'Bodrum', 37.0519, 27.2281, 950.00, FALSE, TRUE, 1, U&'Bodrum Ta\015f Ev Tiny House', TRUE, 3),
(7, TIMESTAMP '2026-05-21 18:38:29.844957', FALSE, TIMESTAMP '2026-05-21 18:38:29.844957', 0, TRUE, U&'Abant Tabiat Park\0131 Giri\015fi', FALSE, 4.75, 1, 2, 4, 'Bolu', 75.00, U&'Abant G\00f6l\00fc manzaral\0131, k\0131\015f-yaz her mevsim keyifli bir ka\00e7amak noktas\0131. \015e\00f6mineli oturma odas\0131 ve geni\015f balkon.', 'Mudurnu', 40.6013, 31.2735, 480.00, TRUE, TRUE, 2, U&'Abant G\00f6l\00fc Orman Ka\00e7ama\011f\0131', TRUE, 2),
(8, TIMESTAMP '2026-05-21 18:38:29.848405', FALSE, TIMESTAMP '2026-05-21 18:38:29.848405', 0, TRUE, U&'Ala\00e7at\0131 Mahallesi 3001 Sk. No:12', TRUE, 4.65, 1, 1, 2, U&'\0130zmir', 100.00, U&'Ala\00e7at\0131''n\0131n renkli sokaklar\0131nda, yel de\011firmenlerine yak\0131n konumda \015firin bir tiny house. S\00f6rf i\00e7in m\00fckemmel r\00fczg\00e2r ko\015fullar\0131.', U&'\00c7e\015fme', 38.2783, 26.3731, 780.00, TRUE, FALSE, 1, U&'Ala\00e7at\0131 R\00fczg\00e2r Evi', TRUE, 3),
(9, TIMESTAMP '2026-05-21 18:38:29.850481', FALSE, TIMESTAMP '2026-05-21 18:38:29.850481', 0, TRUE, U&'Uzung\00f6l Mah. G\00f6l Kenar\0131', FALSE, 4.55, 1, 2, 3, 'Trabzon', 50.00, U&'Uzung\00f6l''\00fcn b\00fcy\00fcleyici manzaras\0131na sahip, geleneksel Karadeniz mimarisinde ah\015fap tiny house. \00c7ay bah\00e7eleri aras\0131nda huzur.', U&'\00c7aykara', 40.6118, 40.29, 420.00, TRUE, TRUE, 1, U&'Uzung\00f6l Yayla Evi', TRUE, 2);
